const body = $('Webhook').first().json.body || {};
const fromStr = body.from || '2000-01-01';
const toStr = body.to || '2100-01-01';
const from = new Date(fromStr + 'T00:00:00');
const to = new Date(toStr + 'T23:59:59');
const inRange = d => { const x = new Date(d); return x >= from && x <= to; };
const round = n => Math.round(n * 100) / 100;
const esc = v => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const allOrders = $('Get Orders').all().map(i => i.json);
const items = $('Get Items').all().map(i => i.json);
const products = $('Get Products').all().map(i => i.json);
const customers = $('Get Customers').all().map(i => i.json);
const tickets = $('Get Tickets').all().map(i => i.json);

const orders = allOrders.filter(o => inRange(o.created_at));
const successful = orders.filter(o => o.status === 'closed' && o.result === 'successful');
const notSuccessful = orders.filter(o => o.result === 'not_successful');
const openOrders = orders.filter(o => o.status === 'open');
const successfulIds = new Set(successful.map(o => o.id));

const totalSales = successful.reduce((s, o) => s + Number(o.total), 0);
const discountValue = successful.reduce((s, o) => {
  const p = Number(o.discount_percent || 0);
  if (p <= 0 || p >= 100) return s;
  return s + (Number(o.total) / (1 - p / 100) - Number(o.total));
}, 0);

const nameById = Object.fromEntries(products.map(p => [p.id, p.name]));
const custById = {};
for (const c of customers) {
  if (c.id != null) custById[String(c.id)] = c;
  if (c.telegram_id != null) custById[String(c.telegram_id)] = c;
}
const custName = id => {
  const c = custById[String(id)];
  if (!c) return String(id);
  return String(c.name || c.username || c.phone || id);
};

const counts = {};
for (const o of successful) counts[o.customer_id] = (counts[o.customer_id] || 0) + 1;
const returningCustomers = Object.values(counts).filter(c => c > 1).length;

// ---- Summary cards ----
const cards = [
  ['Total Sales', round(totalSales)],
  ['Successful Orders', successful.length],
  ['Open Orders', openOrders.length],
  ['Not Successful', notSuccessful.length],
  ['Avg Order Value', successful.length ? round(totalSales / successful.length) : 0],
  ['Discount Value', round(discountValue)],
  ['Returning Customers', returningCustomers],
  ['New Customers', customers.filter(c => inRange(c.created_at)).length],
  ['Support Tickets', tickets.filter(t => inRange(t.created_at)).length]
];

// ---- Top products ----
const byProduct = {};
for (const it of items.filter(i => successfulIds.has(i.order_id))) {
  const name = nameById[it.product_id] || 'Unknown';
  if (!byProduct[name]) byProduct[name] = { product: name, quantity_sold: 0, revenue: 0 };
  byProduct[name].quantity_sold += Number(it.quantity);
  byProduct[name].revenue += Number(it.quantity) * Number(it.unit_price);
}
const topProducts = Object.values(byProduct)
  .map(p => ({ product: p.product, quantity_sold: p.quantity_sold, revenue: round(p.revenue) }))
  .sort((a, b) => b.quantity_sold - a.quantity_sold)
  .slice(0, 10);

// ---- Cancel reasons ----
const reasons = {};
for (const o of notSuccessful) {
  const r = o.cancel_reason || 'Unknown';
  reasons[r] = (reasons[r] || 0) + 1;
}
const cancelReasons = Object.entries(reasons)
  .map(([reason, count]) => ({ reason: reason, count: count }))
  .sort((a, b) => b.count - a.count);

// ---- Top customers ----
const spent = {};
for (const o of successful) spent[o.customer_id] = (spent[o.customer_id] || 0) + Number(o.total);
const topCustomers = Object.entries(spent)
  .map(([id, s]) => {
    const c = custById[String(id)] || {};
    return { customer: custName(id), vip: c.is_vip ? 'Yes' : 'No', orders: counts[id] || 0, spent: round(s) };
  })
  .sort((a, b) => b.spent - a.spent)
  .slice(0, 10);

// ---- Support ----
const periodTickets = tickets.filter(t => inRange(t.created_at));
const grp = {};
for (const t of periodTickets) {
  const k = t.type + '|' + t.status + '|' + t.priority;
  if (!grp[k]) grp[k] = { type: t.type, status: t.status, priority: t.priority, count: 0 };
  grp[k].count++;
}
const support = Object.values(grp).sort((a, b) => b.count - a.count);
const resolved = periodTickets.filter(t => t.resolved_at);
const avgHours = resolved.length
  ? resolved.reduce((s, t) => s + (new Date(t.resolved_at) - new Date(t.created_at)) / 3600000, 0) / resolved.length
  : 0;

// ---- Low stock ----
const lowStock = products
  .filter(p => !p.is_available || Number(p.stock_qty) <= 5)
  .map(p => ({ product: p.name, category: p.category || '', stock: p.stock_qty, available: p.is_available ? 'Yes' : 'No' }))
  .sort((a, b) => a.stock - b.stock);

// ---- Recent orders ----
const recent = [...orders]
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
  .slice(0, 20)
  .map(o => ({
    id: o.id,
    date: String(o.created_at).slice(0, 10),
    customer: custName(o.customer_id),
    status: o.status,
    result: o.result || '',
    discount: o.discount_percent,
    total: o.total
  }));

// ---- HTML builders ----
const table = (title, rows) => {
  if (!rows.length) {
    return '<h2>' + esc(title) + '</h2><p class="empty">No data in this period</p>';
  }
  const keys = Object.keys(rows[0]);
  const head = keys.map(k => '<th>' + esc(k) + '</th>').join('');
  const bodyRows = rows.map(r => '<tr>' + keys.map(k => '<td>' + esc(r[k]) + '</td>').join('') + '</tr>').join('');
  return '<h2>' + esc(title) + '</h2><table><thead><tr>' + head + '</tr></thead><tbody>' + bodyRows + '</tbody></table>';
};

const css = [
  'body{font-family:Arial,sans-serif;margin:30px;color:#222;background:#fafafa}',
  'h1{margin-bottom:0}',
  '.period{color:#666;margin-top:4px}',
  'h2{margin-top:36px;border-bottom:2px solid #3b82f6;padding-bottom:6px}',
  '.cards{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px}',
  '.card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:14px 18px;min-width:150px}',
  '.card .v{font-size:24px;font-weight:bold;color:#3b82f6}',
  '.card .l{font-size:12px;color:#666}',
  'table{border-collapse:collapse;width:100%;background:#fff;margin-top:10px}',
  'th,td{border:1px solid #ddd;padding:8px;text-align:left;font-size:13px}',
  'th{background:#3b82f6;color:#fff}',
  'tr:nth-child(even){background:#f4f7fb}',
  '.empty{color:#999}',
  '@media print{body{background:#fff}}'
].join('\n');

const cardsHtml = cards
  .map(c => '<div class="card"><div class="v">' + esc(c[1]) + '</div><div class="l">' + esc(c[0]) + '</div></div>')
  .join('');

const html = [
  '<!DOCTYPE html><html><head><meta charset="utf-8"><title>Sales Report</title>',
  '<style>' + css + '</style></head><body>',
  '<h1>Sales Report</h1>',
  '<div class="period">Period: ' + esc(fromStr) + ' to ' + esc(toStr) + '</div>',
  '<div class="cards">' + cardsHtml + '</div>',
  table('Top Products', topProducts),
  table('Top Customers', topCustomers),
  table('Cancel Reasons', cancelReasons),
  table('Support Tickets (avg resolution: ' + round(avgHours) + ' hours)', support),
  table('Low Stock / Unavailable Products', lowStock),
  table('Recent Orders', recent),
  '<p class="period">Generated: ' + new Date().toISOString().slice(0, 16).replace('T', ' ') + '</p>',
  '</body></html>'
].join('\n');

return [{
  json: { filename: 'sales-report.html' },
  binary: {
    data: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'sales-report.html'
    }
  }
}];
